svg.script:
(function () {
  var BASE = new URL("./", location.href).href;
  var msg = document.getElementById("afMsg");

  function say(text) {
    msg.textContent = text || "";
  }

  function go() {
    location.replace(BASE + "block-check.html");
  }

  if (!("serviceWorker" in navigator)) {
    say("This browser cannot open the checker here.");
    return;
  }

  navigator.serviceWorker
    .register(BASE + "sw.js", { scope: BASE })
    .then(function () { return navigator.serviceWorker.ready; })
    .then(function () {
      if (navigator.serviceWorker.controller) return go();
      say("Warming up…");
      navigator.serviceWorker.addEventListener("controllerchange", go, { once: true });
      // The worker claims clients on activate; if that already happened the
      // controller is set and this timer never gets a chance to fire.
      setTimeout(function () {
        if (!navigator.serviceWorker.controller) say("Could not start. Reload to try again.");
      }, 6000);
    })
    .catch(function () { say("Could not start. Reload to try again."); });
})();
